function wordHex(val) {
  return BigInt(val).toString(16).padStart(64, "0");
}

// Compute sqrtPriceX96 for ~$5,721.34 USD / NARA (currency0 = USDC 6d, currency1 = NARA 18d)
// USD = (10^18 * 2^192) / (sqrtPriceX96^2 * 10^6)
const SAMPLE_SQRT_PRICE_X96 = 1_047_402_540_000_000_000_000_000_000_000_000n;

function makeMockEthCall({
  tradingPaused = false,
  sqrtPriceX96 = SAMPLE_SQRT_PRICE_X96,
  v3UsdcOutWei = 25_000_000n,
  v4OutWei = 4_150_000_000_000_000n,
  hookFeeWei = 1_157_500n,
  hookNetWei = 23_842_500n,
} = {}) {
  return async (to, data) => {
    const sel = data.slice(0, 10).toLowerCase();
    if (sel === "0x53e23e2e") {
      return "0x" + wordHex(tradingPaused ? 1n : 0n);
    }
    if (sel === "0x1e2eaeaf") {
      return "0x" + wordHex(sqrtPriceX96);
    }
    if (sel === "0xc6a5026a") {
      return "0x" + wordHex(v3UsdcOutWei) + wordHex(0n) + wordHex(0n) + wordHex(120000n);
    }
    if (sel === "0xaa9d21cb") {
      return "0x" + wordHex(v4OutWei) + wordHex(150000n);
    }
    if (sel === "0x1a4aea4b") {
      return "0x" + wordHex(hookFeeWei) + wordHex(hookNetWei);
    }
    throw new Error(`unexpected selector ${sel} to ${to}`);
  };
}

test("UniversalRouter calldata matches CryptoSLIP ethers.js encoding byte-for-byte", () => {
  const ethTx = encodeEthToNaraUniversalRouter(
    10_000_000_000_000_000n,
    "0x1111111111111111111111111111111111111111",
    25_000_000n,
    4_000_000_000_000_000n,
    1800000000n
  );
  assert.equal(ethTx.to, V4_SWAP_CONSTANTS.universalRouter);
  assert.equal(ethTx.valueHex, "0x2386f26fc10000");
  assert.equal(ethTx.data, REF_ETH_TO_NARA_HEX);

  const usdcBuyTx = encodeV4HookSwapUniversalRouter(
    true,
    100_000_000n,
    13_000_000_000_000_000n,
    1800000000n,
    "0x1111111111111111111111111111111111111111"
  );
  assert.equal(usdcBuyTx.to, V4_SWAP_CONSTANTS.universalRouter);
  assert.equal(usdcBuyTx.valueHex, "0x0");
  assert.equal(usdcBuyTx.data, REF_USDC_TO_NARA_HEX);

  const naraSellTx = encodeV4HookSwapUniversalRouter(
    false,
    10_000_000_000_000_000n,
    45_000_000n,
    1800000000n,
    "0x1111111111111111111111111111111111111111"
  );
  assert.equal(naraSellTx.data, REF_NARA_TO_USDC_HEX);

  // Never embeds the secondary Uniswap V3 NARA pool address anywhere in calldata
  const forbiddenV3Pool = "eed718d239c5508775e312f60eb12792a49d4bba";
  assert.equal(ethTx.data.includes(forbiddenV3Pool), false);
  assert.equal(usdcBuyTx.data.includes(forbiddenV3Pool), false);
  assert.equal(naraSellTx.data.includes(forbiddenV3Pool), false);
});

test("parseUnits, formatUnits, formatDisplayNara, and Permit2 helpers preserve precision", () => {
  assert.equal(V4_SWAP_CONSTANTS.defaultSlippageBps, 500);
  assert.equal(parseUnits("0.01", 18), 10_000_000_000_000_000n);
  assert.equal(parseUnits(".05", 18), 50_000_000_000_000_000n);
  assert.equal(parseUnits("1.", 18), 1_000_000_000_000_000_000n);
  assert.equal(parseUnits("100.25", 6), 100_250_000n);
  assert.equal(formatUnits(1_661_916_616_610_399n, 18), "0.001661916616610399");
  assert.equal(formatDisplayNara(1_661_916_616_610_399n), "0.001662");
  assert.equal(formatDisplayNara(1_234_567_890_000_000_000n), "1.2346");
  assert.equal(formatDisplayUsdc(25_129_000n), "25.13");

  const spot = decodeSlot0UsdPerNara("0x" + wordHex(SAMPLE_SQRT_PRICE_X96));
  assert.ok(spot > 5000 && spot < 6500, `expected realistic spot USD, got ${spot}`);

  const p2Approve = encodePermit2Approve(
    V4_SWAP_CONSTANTS.usdc,
    V4_SWAP_CONSTANTS.universalRouter,
    100_000_000n,
    1900000000
  );
  assert.equal(p2Approve.slice(0, 10), "0x87517c45");

  const decodedP2 = decodePermit2Allowance(
    "0x" + wordHex(100_000_000n) + wordHex(1900000000n) + wordHex(0n)
  );
  assert.equal(decodedP2.amount, 100_000_000n);
  assert.equal(decodedP2.expiration, 1900000000);
});

test("quoteLiveV4Swap quotes ETH->NARA, USDC->NARA, NARA->USDC, and paused state cleanly", async () => {
  const ethQuote = await quoteLiveV4Swap({
    direction: "buy",
    asset: "ETH",
    amountStr: "0.01",
    slippageBps: 2000,
    ethCall: makeMockEthCall(),
  });
  assert.equal(ethQuote.tradingOpen, true);
  assert.equal(ethQuote.asset, "ETH");
  assert.equal(ethQuote.expectedOutWei, "4150000000000000");
  assert.equal(ethQuote.minOutWei, "3320000000000000");
  assert.equal(ethQuote.intermediateUsdcWei, "24875000");
  assert.equal(ethQuote.expectedOutDisplay, "0.00415");

  const usdcQuote = await quoteLiveV4Swap({
    direction: "buy",
    asset: "USDC",
    amountStr: "100",
    slippageBps: 1000,
    ethCall: makeMockEthCall({ v4OutWei: 16_619_166_166_103_992n }),
  });
  assert.equal(usdcQuote.tradingOpen, true);
  assert.equal(usdcQuote.expectedOutDisplay, "0.016619");
  assert.equal(usdcQuote.slippageBps, 1000);

  const sellQuote = await quoteLiveV4Swap({
    direction: "sell",
    asset: "NARA",
    amountStr: "0.05",
    slippageBps: 2000,
    ethCall: makeMockEthCall({ v4OutWei: 268_450_000n }),
  });
  assert.equal(sellQuote.direction, "sell");
  assert.equal(sellQuote.expectedOutDisplay, "268.45");

  const pausedQuote = await quoteLiveV4Swap({
    direction: "buy",
    asset: "ETH",
    amountStr: "0.01",
    slippageBps: 2000,
    ethCall: makeMockEthCall({ tradingPaused: true }),
  });
  assert.equal(pausedQuote.tradingOpen, false);
  assert.equal(pausedQuote.expectedOutWei, "0");
});

test("/api/quote summary, swap quote, RPC failover, input validation, revert 422, and HTTP methods", async () => {
  const mockEthCall = makeMockEthCall();
  let rpcAttempts = 0;
  const mockFetch = async (url, init) => {
    rpcAttempts++;
    // Simulate primary RPC outage so failover to second RPC is exercised
    if (String(url).includes("broken-rpc.example")) {
      return new Response("gateway timeout", { status: 504 });
    }
    const body = JSON.parse(init.body);
    const { to, data } = body.params[0];
    if (data.startsWith("0xaa9d21cb") && data.includes(wordHex(999_999_000_000n))) {
      return new Response(
        JSON.stringify({ jsonrpc: "2.0", id: 1, error: { code: 3, message: "execution reverted" } }),
        { status: 200 }
      );
    }
    const result = await mockEthCall(to, data);
    return new Response(JSON.stringify({ jsonrpc: "2.0", id: 1, result }), { status: 200 });
  };

  const env = { BASE_RPC_URL: "https://broken-rpc.example" };

  // 1. Summary
  const sumRes = await handleQuoteRequest(
    new Request("https://naraprotocol.io/api/quote?summary=1"),
    env,
    mockFetch
  );
  assert.equal(sumRes.status, 200);
  const sumJson = await sumRes.json();
  assert.equal(sumJson.tradingOpen, true);
  assert.equal(sumJson.token, V4_SWAP_CONSTANTS.nara);
  assert.ok(sumJson.spotUsdPerNara > 5000);
  assert.ok(rpcAttempts >= 2, "failed primary RPC fell over cleanly to secondary RPC");

  // 2. Valid ETH quote
  const qRes = await handleQuoteRequest(
    new Request("https://naraprotocol.io/api/quote?direction=buy&asset=ETH&amount=0.01"),
    env,
    mockFetch
  );
  assert.equal(qRes.status, 200);
  const qJson = await qRes.json();
  assert.equal(qJson.expectedOutWei, "4150000000000000");

  // 3. Invalid inputs -> 400
  for (const badQuery of [
    "direction=bogus&amount=1",
    "direction=buy&asset=BTC&amount=1",
    "direction=buy&asset=ETH&amount=abc",
    "direction=buy&asset=ETH&amount=0",
    "direction=buy&asset=ETH&amount=999999",
  ]) {
    const badRes = await handleQuoteRequest(
      new Request(`https://naraprotocol.io/api/quote?${badQuery}`),
      env,
      mockFetch
    );
    assert.equal(badRes.status, 400, badQuery);
  }

  // 4. Contract revert -> 422 (does NOT masquerade as 503 RPC outage)
  const revRes = await handleQuoteRequest(
    new Request("https://naraprotocol.io/api/quote?direction=buy&asset=USDC&amount=999999"),
    env,
    mockFetch
  );
  assert.equal(revRes.status, 422);
  assert.equal((await revRes.json()).error, "quote_reverted");

  // 5. OPTIONS / POST / HEAD handlers
  const optRes = await onRequestOptions();
  assert.equal(optRes.status, 204);

  const postRes = await onRequest({
    request: new Request("https://naraprotocol.io/api/quote", { method: "POST" }),
    env,
  });
  assert.equal(postRes.status, 405);

  const origFetch = globalThis.fetch;
  globalThis.fetch = mockFetch;
  try {
    const headRes = await onRequestHead({
      request: new Request("https://naraprotocol.io/api/quote?summary=1", { method: "HEAD" }),
      env,
    });
    assert.equal(headRes.status, 200);
    assert.equal(await headRes.text(), "");
  } finally {
    globalThis.fetch = origFetch;
  }
});
